import{_ as t,o as a,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"原理深挖总览","description":"","frontmatter":{"title":"原理深挖总览"},"headers":[],"relativePath":"frontend/deep-dive/index.md","filePath":"frontend/deep-dive/index.md","lastUpdated":1785666337000}'),i={name:"frontend/deep-dive/index.md"};function l(n,e,o,h,c,p){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="原理深挖总览" tabindex="-1">原理深挖总览 <a class="header-anchor" href="#原理深挖总览" aria-label="Permalink to &quot;原理深挖总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>原理深挖从“会使用”继续追问到“为什么成立”。它关注浏览器与网络协议、JavaScript 运行时、TypeScript 编译器、构建工具和框架内部的关键机制，并通过源码、规范、实验和性能数据验证结论。</p><p>这里不是面试题集合，也不是为了记忆实现细节。真正有价值的原理知识，应当能够帮助定位复杂问题、判断抽象边界、理解性能代价，并在工具或框架变化后继续有效。</p><h2 id="原理地图" tabindex="-1">原理地图 <a class="header-anchor" href="#原理地图" aria-label="Permalink to &quot;原理地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>深挖对象</th><th>要解决的问题</th></tr></thead><tbody><tr><td><a href="/frontend/deep-dive/browser/rendering-pipeline">浏览器原理</a></td><td>渲染流水线、事件循环、输入与合成、交互延迟和进程隔离</td><td>页面为什么在特定时机更新、卡顿或丢帧，以及浏览器如何建立安全边界</td></tr><tr><td><a href="/frontend/deep-dive/javascript/engine">JavaScript 运行时</a></td><td>引擎、JIT、垃圾回收和 Promise</td><td>代码如何执行、优化、暂停和释放内存</td></tr><tr><td><a href="/frontend/deep-dive/network/http2">网络协议原理</a></td><td>HTTP/2、QUIC 与 HTTP/3</td><td>连接、流、多路复用和丢包恢复如何影响传输行为</td></tr><tr><td><a href="/frontend/deep-dive/typescript/compiler">TypeScript 编译器</a></td><td>编译流水线、符号绑定、类型检查与控制流分析</td><td>类型信息如何被建立、传播、收窄和计算</td></tr><tr><td><a href="/frontend/deep-dive/build/module-graph">构建工具原理</a></td><td>模块图、Tree Shaking、HMR 和 Source Map</td><td>工具如何分析代码并生成开发与生产产物</td></tr><tr><td><a href="/frontend/deep-dive/react/fiber-reconciliation">React 原理</a></td><td>Fiber、Scheduler、Hooks、Lane 和 RSC</td><td>React 如何调度、渲染和提交更新</td></tr><tr><td><a href="/frontend/deep-dive/vue/reactivity">Vue 原理</a></td><td>响应式、模板编译、Block Tree、Renderer 和 Scheduler</td><td>Vue 如何追踪依赖并生成最小更新</td></tr><tr><td><a href="/frontend/deep-dive/research/source-reading">源码、规范与实验</a></td><td>源码追踪、规范与设计文档、最小实验和基准测试</td><td>如何得到可复现、可解释且标明版本的技术结论</td></tr></tbody></table><h2 id="深挖方法" tabindex="-1">深挖方法 <a class="header-anchor" href="#深挖方法" aria-label="Permalink to &quot;深挖方法&quot;">​</a></h2><p>每个专题都应遵循相同的研究闭环：</p><ol><li>从可观察的问题开始，记录现象和运行环境。</li><li>提出可以被证伪的假设，而不是直接寻找支持结论的代码。</li><li>构造最小实验，使用时间线、调用栈、性能数据或产物验证行为。</li><li>阅读规范、设计文档和关键源码，追踪数据结构与控制流。</li><li>回到公开 API，说明内部机制对实际开发有什么影响。</li><li>记录版本、适用条件和未知边界，避免把当前实现当成永久契约。</li></ol><h2 id="推荐前置" tabindex="-1">推荐前置 <a class="header-anchor" href="#推荐前置" aria-label="Permalink to &quot;推荐前置&quot;">​</a></h2><p>开始深挖前，应先掌握对应的<a href="/frontend/guide/core/">核心知识</a>和基本调试方法。例如，阅读 React Scheduler 前应理解组件更新、Transition 和浏览器任务调度；研究 Tree Shaking 前应理解 ESM 静态结构与构建产物。</p><p>不建议严格从第一篇顺序读到最后一篇。更有效的方式是围绕真实问题选择专题，例如：</p><ul><li>页面交互卡顿：浏览器渲染、事件循环、长任务和框架调度。</li><li>内存持续增长：JavaScript 垃圾回收、浏览器生命周期和框架副作用。</li><li>构建产物异常：模块图、Tree Shaking、Chunk 和 Source Map。</li><li>更新结果不符合预期：React 更新队列或 Vue 响应式与 Scheduler。</li></ul><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>以稳定概念和公开 API 为主。</li><li><a href="/frontend/topics/">专题进阶</a>建立算法、设计模式、可视化、跨端和 AI 等独立领域的知识体系。</li><li>本模块研究内部机制，但不会把未公开实现当作业务代码依赖。</li><li><a href="/frontend/guide/engineering/">工程体系</a>使用这些原理建立调试、性能和构建能力。</li><li><a href="/frontend/practices/">项目实战</a>通过真实系统检验原理能否转化为解决方案。</li></ul><h2 id="掌握标准" tabindex="-1">掌握标准 <a class="header-anchor" href="#掌握标准" aria-label="Permalink to &quot;掌握标准&quot;">​</a></h2><ul><li>能用实验和工具证明结论，而不是只复述文章或源码注释。</li><li>能画出关键数据结构、控制流和调度时序。</li><li>能区分标准、公开契约、框架约定与内部实现。</li><li>能把原理转化为调试策略、性能判断或架构约束。</li><li>能明确结论对应的版本、环境和适用范围。</li></ul>',17)])])}const s=t(i,[["render",l]]);export{u as __pageData,s as default};
